CALL pg_temp.version_write('lineup moves',$cmd$SELECT public.set_player_slot_moves_atomic(member_ids[1],league_id,season_id,current_date,1,jsonb_build_array(jsonb_build_object('player_id',players[1],'slot_type',CASE WHEN EXISTS(SELECT 1 FROM public.weekly_lineups WHERE league_id=f.league_id AND member_id=f.member_ids[1] AND player_id=f.players[1] AND game_date=current_date AND slot_type='PG') THEN 'BE' ELSE 'PG' END))) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('automatic lineup',$cmd$SELECT public.auto_set_lineup_atomic(member_ids[1],league_id,season_id,current_date,jsonb_build_array(jsonb_build_object('player_id',players[1],'slot_type',CASE WHEN EXISTS(SELECT 1 FROM public.weekly_lineups WHERE league_id=f.league_id AND member_id=f.member_ids[1] AND player_id=f.players[1] AND game_date=current_date AND slot_type='PG') THEN 'BE' ELSE 'PG' END))) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('service lineup',$cmd$SELECT public.auto_set_lineup_service_atomic(member_ids[1],league_id,season_id,current_date,jsonb_build_array(jsonb_build_object('player_id',players[1],'slot_type',CASE WHEN EXISTS(SELECT 1 FROM public.weekly_lineups WHERE league_id=f.league_id AND member_id=f.member_ids[1] AND player_id=f.players[1] AND game_date=current_date AND slot_type='PG') THEN 'BE' ELSE 'PG' END))) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('inactive overflow player',$cmd$SELECT public.toggle_ir_atomic((SELECT id FROM public.roster_players WHERE player_id=f.players[5] AND league_id=f.league_id),true,user_ids[1]) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('activate with overflow',$cmd$SELECT public.activate_roster_player_with_overflow_atomic((SELECT id FROM public.roster_players WHERE player_id=f.players[5] AND league_id=f.league_id),'ir',(SELECT id FROM public.roster_players WHERE player_id=f.players[6] AND league_id=f.league_id),'drop') FROM version_fixture f$cmd$);
CALL pg_temp.version_write('compound retired pickup rolls back',$cmd$SELECT public.drop_and_add_free_agent_atomic((SELECT id FROM public.roster_players WHERE player_id=f.players[5] AND league_id=f.league_id),member_ids[1],league_id,players[8]) FROM version_fixture f$cmd$,0,'Every pickup requires a scheduled waiver claim.%');
CALL pg_temp.version_write('drop one argument',$cmd$SELECT public.drop_player_atomic((SELECT id FROM public.roster_players WHERE player_id=f.players[5] AND league_id=f.league_id)) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('drop two arguments',$cmd$SELECT public.drop_player_atomic((SELECT id FROM public.roster_players WHERE player_id=f.players[7] AND league_id=f.league_id),f.season_id) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('drop three arguments',$cmd$SELECT public.drop_player_atomic((SELECT id FROM public.roster_players WHERE player_id=f.players[1] AND league_id=f.league_id),f.season_id,NULL) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('ready waiver clearance',$cmd$UPDATE public.waiver_wire_log SET clears_at=now()-interval '1 minute' WHERE league_id=(SELECT league_id FROM version_fixture) AND cleared_at IS NULL$cmd$);
CALL pg_temp.version_write('waiver clearance worker',$cmd$SELECT public.expire_waiver_wire_logs()$cmd$);
CALL pg_temp.version_write('register push token',$cmd$SELECT public.register_push_token_atomic(user_ids[1],'version-test-token',repeat('0',64)) FROM version_fixture$cmd$,0);
CALL pg_temp.version_write('revoke push token',$cmd$SELECT public.revoke_push_token_atomic('version-test-token',repeat('0',64))$cmd$,0);
CALL pg_temp.version_write('register token again',$cmd$SELECT public.register_push_token_atomic(user_ids[1],'version-test-token',repeat('0',64)) FROM version_fixture$cmd$,0);
CALL pg_temp.version_write('clear push token',$cmd$SELECT public.clear_push_token_for_user_atomic(user_ids[1],'version-test-token') FROM version_fixture$cmd$,0);
